          privacy: "\u041E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0430 \u0434\u0430\u043D\u043D\u044B\u0445",
          privacyText: "\u041A\u043E\u043D\u0442\u0430\u043A\u0442\u044B \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442\u0441\u044F \u0434\u043B\u044F \u043E\u0431\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u044F \u043F\u0440\u043E\u0435\u043A\u0442\u0430 \u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0443 \u0441\u0430\u0439\u0442\u0430. \u0417\u0430\u044F\u0432\u043A\u0438 \u0445\u0440\u0430\u043D\u044F\u0442\u0441\u044F \u0432 Supabase. \u0427\u0442\u043E\u0431\u044B \u0443\u0434\u0430\u043B\u0438\u0442\u044C \u0437\u0430\u044F\u0432\u043A\u0443, \u043D\u0430\u043F\u0438\u0448\u0438\u0442\u0435 \u0432 WhatsApp. \u041D\u0435 \u0443\u043A\u0430\u0437\u044B\u0432\u0430\u0439\u0442\u0435 \u043F\u0430\u0440\u043E\u043B\u0438, \u043F\u043B\u0430\u0442\u0451\u0436\u043D\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u0438 \u0434\u0440\u0443\u0433\u0443\u044E \u043B\u0438\u0448\u043D\u044E\u044E \u043B\u0438\u0447\u043D\u0443\u044E \u0438\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044E.",
          success: "\u0417\u0430\u044F\u0432\u043A\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0430. \u0421\u043F\u0430\u0441\u0438\u0431\u043E!",
          successDesc: "\u041C\u043E\u0436\u043D\u043E \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u043E\u0431\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0435 \u0432 WhatsApp.",
