          rights: "\u0414\u0438\u0437\u0430\u0439\u043D \u0438 \u0440\u0430\u0437\u0440\u0430\u0431\u043E\u0442\u043A\u0430 \u2014 \u0421\u0430\u0431\u0438\u0440 \u0420\u0430\u043A\u0438\u0448\u043E\u0432",
