          result: "\u0427\u0442\u043E \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u043A\u043E\u043D\u0446\u0435\u043F\u0446\u0438\u044F",
          caseStack: "\u0421\u043A\u0440\u0438\u043D\u0448\u043E\u0442\u044B \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442 \u0432\u0438\u0437\u0443\u0430\u043B\u044C\u043D\u0443\u044E \u0441\u0442\u0440\u0443\u043A\u0442\u0443\u0440\u0443 \u0438 \u0432\u0451\u0440\u0441\u0442\u043A\u0443 \u0441\u0442\u0440\u0430\u043D\u0438\u0446. \u0422\u0435\u0445\u043D\u043E\u043B\u043E\u0433\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0441\u0442\u0435\u043A, \u0438\u043D\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0438 \u0438 \u0441\u0435\u0440\u0432\u0435\u0440\u043D\u0430\u044F \u043B\u043E\u0433\u0438\u043A\u0430 \u043F\u043E \u0441\u043D\u0438\u043C\u043A\u0430\u043C \u043D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u044E\u0442\u0441\u044F.",
